package com.autojobapply.discovery;
import com.autojobapply.config.Config; import com.autojobapply.model.Job; import com.google.gson.*; import java.net.URI; import java.net.http.*; import java.time.Duration; import java.util.*;
/** Public, documented job feeds only. No LinkedIn scraping or login automation. */
public final class JobDiscovery {
 private final Config config; private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(20)).build(); public JobDiscovery(Config c){config=c;}
 public List<Job> discover(){ Map<String,Job> found=new LinkedHashMap<>(); remotive().forEach(j->found.put(j.identity(),j)); for(String board:config.greenhouseBoards()) greenhouse(board).forEach(j->found.put(j.identity(),j)); return found.values().stream().filter(this::relevant).limit(config.maxDiscovered()).toList(); }
 private List<Job> remotive(){ try { JsonArray jobs=get("https://remotive.com/api/remote-jobs?category=software-dev").getAsJsonObject().getAsJsonArray("jobs"); List<Job> out=new ArrayList<>(); for(JsonElement e:jobs){JsonObject o=e.getAsJsonObject(); out.add(new Job("Remotive public API",str(o,"company_name"),str(o,"title"),str(o,"candidate_required_location"),strip(str(o,"description")),str(o,"id"),str(o,"url"),str(o,"url")));} return out;}catch(Exception ignored){return List.of();} }
 private List<Job> greenhouse(String board){try {JsonArray jobs=get("https://boards-api.greenhouse.io/v1/boards/"+board+"/jobs?content=true").getAsJsonObject().getAsJsonArray("jobs"); List<Job> out=new ArrayList<>(); for(JsonElement e:jobs){JsonObject o=e.getAsJsonObject(); String location=o.has("location")?str(o.getAsJsonObject("location"),"name"):"";out.add(new Job("Greenhouse public board",board,str(o,"title"),location,strip(str(o,"content")),str(o,"id"),str(o,"absolute_url"),str(o,"absolute_url")));}return out;}catch(Exception ignored){return List.of();}}
 private JsonElement get(String url)throws Exception{HttpRequest r=HttpRequest.newBuilder(URI.create(url)).header("User-Agent","AutoJobApplyAgent/1.0 (authorized public-feed discovery)").timeout(Duration.ofSeconds(45)).GET().build();HttpResponse<String>x=http.send(r,HttpResponse.BodyHandlers.ofString());if(x.statusCode()/100!=2)throw new IllegalStateException("HTTP "+x.statusCode());return JsonParser.parseString(x.body());}
 private boolean relevant(Job j){String s=(j.title()+" "+j.description()).toLowerCase(); boolean role=s.matches("(?s).*\\b(principal|staff|architect|lead software|lead java)\\b.*");boolean tech=s.matches("(?s).*\\b(java|backend|software|distributed|microservices)\\b.*");String l=j.location().toLowerCase();boolean place=config.includeRemote()&&l.contains("remote")||l.matches(".*(san francisco|san jose|bay area|california|ca|palo alto|sunnyvale|mountain view|santa clara|redwood city|oakland|berkeley).*" );return role&&tech&&place;}
 private static String str(JsonObject o,String k){return o.has(k)&&!o.get(k).isJsonNull()?o.get(k).getAsString():"";} private static String strip(String s){return s.replaceAll("<[^>]*>"," ").replaceAll("&[a-zA-Z#0-9]+;"," ").replaceAll("\\s+"," ").trim();}
}
